import{_ as e,o as s,c as r,a5 as n}from"./chunks/framework.DJo0M80U.js";const p=JSON.parse('{"title":"第十四章：支持多入口打包 + 模块共享分析（MPA - 微前端模式）","description":"非常棒！欢迎进入本系列最后一个里程碑： 🏁 ✅ 本章目标： 支持多个入口（多个页面 / 子应用） 为每个入口单独打包 自动提取 共享模块 ，生成公共依赖 chunk 模拟 Vite/Webpack 的 SplitChunks 与多入口输出功能 🧱 示例结构 multientryb。","frontmatter":{"title":"第十四章：支持多入口打包 + 模块共享分析（MPA - 微前端模式）","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","模块化与工程化"],"description":"非常棒！欢迎进入本系列最后一个里程碑： 🏁 ✅ 本章目标： 支持多个入口（多个页面 / 子应用） 为每个入口单独打包 自动提取 共享模块 ，生成公共依赖 chunk 模拟 Vite/Webpack 的 SplitChunks 与多入口输出功能 🧱 示例结构 multientryb。","sidebarWeight":50,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/12-模块化编程/实现esmodule/第十四章：支持多入口打包 + 模块共享分析（MPA - 微前端模式）.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/06-模块化与工程化/实现esmodule/第十四章：支持多入口打包 + 模块共享分析（MPA - 微前端模式）.md","filePath":"posts/JavaScript系统教程/06-模块化与工程化/实现esmodule/第十四章：支持多入口打包 + 模块共享分析（MPA - 微前端模式）.md"}'),o={name:"posts/JavaScript系统教程/06-模块化与工程化/实现esmodule/第十四章：支持多入口打包 + 模块共享分析（MPA - 微前端模式）.md"};function a(d,t,l,i,g,u){return s(),r("div",null,[...t[0]||(t[0]=[n('<div><h1 id="第十四章-支持多入口打包-模块共享分析-mpa-微前端模式" tabindex="-1">第十四章：支持多入口打包 + 模块共享分析（MPA - 微前端模式） <a class="header-anchor" href="#第十四章-支持多入口打包-模块共享分析-mpa-微前端模式" aria-label="Permalink to &quot;第十四章：支持多入口打包 + 模块共享分析（MPA - 微前端模式）&quot;">​</a></h1><blockquote><p>本节目标：理解“第十四章：支持多入口打包 + 模块共享分析（MPA - 微前端模式）”的核心思路，并能把它用于实际开发或面试表达。 非常棒！欢迎进入本系列最后一个里程碑：</p></blockquote><p><strong>🏁</strong> ✅ 本章目标：</p><ul><li>支持多个入口（多个页面 / 子应用）</li><li>为每个入口单独打包</li><li>自动提取<strong>共享模块</strong>，生成公共依赖 chunk</li><li>模拟 Vite/Webpack 的 SplitChunks 与多入口输出功能</li></ul><p><strong>🧱</strong> <strong>示例结构</strong> multientrybundler/├── src/│ ├── admin/│ │ └── index.mjs # 管理后台入口│ ├── user/│ │ └── index.mjs # 用户端入口│ ├── shared/│ │ ├── api.mjs # 所有页面共享模块│ │ └── util.mjs├── bundler.js # 多入口打包器└── dist/ ├── admin.bundle.js ├── user.bundle.js └── shared.bundle.js # ✅ 自动提取共享 chunk</p><p><strong>✅</strong> <strong>示例模块</strong><strong>📄</strong> <strong>shared/api.mjs</strong> export const fetchData = () =&gt; &#39;Fetched data&#39;; <strong>📄</strong> <strong>shared/util.mjs</strong> export const log = msg =&gt; console.log(&#39;[LOG]&#39;, msg); <strong>📄</strong> <strong>admin/index.mjs</strong> import { fetchData } from &#39;../shared/api.mjs&#39;;import { log } from &#39;../shared/util.mjs&#39;; log(&#39;Admin:&#39; + fetchData()); <strong>📄</strong> <strong>user/index.mjs</strong> import { fetchData } from &#39;../shared/api.mjs&#39;;console.log(&#39;User page fetch:&#39;, fetchData());</p><p><strong>✍️</strong> <strong>bundler.js 核心逻辑（多入口 + chunk 拆分）</strong><strong>✅</strong> <strong>步骤 1：支持多个 entry</strong> const entryMap = { admin: &#39;./src/admin/index.mjs&#39;, user: &#39;./src/user/index.mjs&#39;};</p><p><strong>✅</strong> <strong>步骤 2：构建每个入口的模块依赖图（使用 DFS）</strong> let globalId = 0;const allModules = new Map(); function collectModules(entryPath) { const visited = new Set(); const queue = [entryPath]; const result = []; while (queue.length &gt; 0) { const current = path.resolve(queue.pop()); if (visited.has(current)) continue; visited.add(current); const raw = fs.readFileSync(current, &#39;utf-8&#39;); const ast = acorn.parse(raw, { sourceType: &#39;module&#39;, ecmaVersion: &#39;latest&#39; }); const deps = []; for (const node of ast.body) { if (node.type === &#39;ImportDeclaration&#39;) { deps.push(node.source.value); } } const mod = { id: globalId++, name: current, rawCode: raw, deps: [], dependents: [], }; result.push(mod); allModules.set(current, mod); for (const dep of deps) { const full = path.resolve(path.dirname(current), dep); mod.deps.push(full); queue.push(full); } } return result;}</p><p><strong>✅</strong> <strong>步骤 3：分析模块出现次数 → 提取共享模块</strong> function findSharedModules(modGraphs) { const countMap = {}; modGraphs.flat().forEach(m =&gt; { countMap[m.name] = (countMap[m.name] || 0) + 1; }); return Object.entries(countMap) .filter(([_, count]) =&gt; count &gt; 1) .map(([name]) =&gt; name);}</p><p><strong>✅</strong> <strong>步骤 4：为每个入口输出一个 bundle，同时输出 shared.bundle.js</strong> function generateChunk(mods, sharedNames, outFile) { const used = mods.filter(m =&gt; !sharedNames.includes(m.name)); const code = used.map(m =&gt; transform(m)).join(&#39;\\n&#39;); fs.writeFileSync(<code>dist/${outFile}</code>, code, &#39;utf-8&#39;);} function generateSharedChunk(sharedNames) { const sharedMods = Array.from(allModules.values()).filter(m =&gt; sharedNames.includes(m.name)); const code = sharedMods.map(m =&gt; transform(m)).join(&#39;\\n&#39;); fs.writeFileSync(<code>dist/shared.bundle.js</code>, code, &#39;utf-8&#39;);} transform(m) 就是我们之前章节中用来将 export 转为 exports.xxx = xxx 的转换器。</p><p><strong>✅</strong> <strong>最后完整执行流程</strong> const allGraphs = Object.entries(entryMap).map(([name, file]) =&gt; { return { name, modules: collectModules(file) };}); const sharedNames = findSharedModules(allGraphs.map(g =&gt; g.modules));generateSharedChunk(sharedNames); for (const graph of allGraphs) { generateChunk(graph.modules, sharedNames, <code>${graph.name}.bundle.js</code>);} console.log(&#39;✅ 多入口打包完成，已拆分 shared.bundle.js&#39;);</p><p><strong>✅</strong> <strong>执行结果</strong> node bundler.js 生成： dist/├── admin.bundle.js├── user.bundle.js└── shared.bundle.js</p><p><strong>✅</strong> <strong>本章成就</strong></p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>功能</strong></td><td><strong>实现</strong></td></tr><tr><td>多入口打包支持（admin/user）</td><td>✔</td></tr><tr><td>自动构建依赖图</td><td>✔</td></tr><tr><td>分析共享模块并提取 shared chunk</td><td>✔</td></tr><tr><td>输出多个 bundle 文件</td><td>✔</td></tr><tr><td>支持微前端 / 多页面打包</td><td>✔</td></tr></tbody></table><p><strong>🎉</strong> <strong>恭喜！</strong> 你已经手工实现了一个具备以下核心能力的<strong>迷你打包器</strong>：</p><ul><li>✅ ESM/CJS/JSON 全支持</li><li>✅ import() 动态导入</li><li>✅ top-level await</li><li>✅ Tree Shaking</li><li>✅ 可视化依赖图（.dot + HTML）</li><li>✅ 多入口打包与共享模块提取</li></ul><p><strong>🧠</strong> <strong>想进一步？</strong> 以下是可以继续优化的方向：</p><ol><li><strong>生成完整 Source Map</strong></li><li><strong>使用 Rollup 插件体系结构实现扩展</strong></li><li><strong>构建成 npm 包 / CLI 工具发布</strong></li><li><strong>加入压缩（如 Terser）支持</strong></li><li><strong>服务端打包 SSR 支持</strong></li></ol><p>如果你对其中某项感兴趣，我们可以继续深挖！你想继续挑战哪个方向？💪 &gt; 来自 &lt;<a href="https://chatgpt.com/c/6805aef6-e7b4-8004-ab43-9a137f666985" target="_blank" rel="noreferrer">https://chatgpt.com/c/6805aef6-e7b4-8004-ab43-9a137f666985</a>&gt;</p></div>',1)])])}const m=e(o,[["render",a]]);export{p as __pageData,m as default};
